CREATE POLICY "tracking_sample" ON "driver_tracking_sessions" AS PERMISSIVE FOR UPDATE TO public USING ("driver_tracking_sessions"."token_hash"=NULLIF(current_setting('rove.tracking_hash',true),'') AND current_setting('rove.tracking_mode',true)='sample' AND "driver_tracking_sessions"."driver_id"=NULLIF(current_setting('rove.tracking_driver',true),'')::uuid) WITH CHECK ("driver_tracking_sessions"."token_hash"=NULLIF(current_setting('rove.tracking_hash',true),'') AND current_setting('rove.tracking_mode',true)='sample' AND "driver_tracking_sessions"."driver_id"=NULLIF(current_setting('rove.tracking_driver',true),'')::uuid);--> statement-breakpoint
